public class Main {
    static long calls = 0;
    static long[] memo = new long[91];

    // Plain recursion: the same subproblem is solved again and again.
    static long naive(int n) {
        calls++;
        if (n < 2) return n;
        return naive(n - 1) + naive(n - 2);
    }

    // DP (memoization): solve each n once, store it, reuse it.
    static long fast(int n) {
        calls++;
        if (n < 2) return n;
        if (memo[n] != 0) return memo[n];   // already solved: reuse
        memo[n] = fast(n - 1) + fast(n - 2);
        return memo[n];
    }

    public static void main(String[] args) {
        int n = 30;
        System.out.println("n = " + n);
        calls = 0;
        long a = naive(n);
        System.out.println("plain recursion: fib = " + a + ", calls = " + calls);
        calls = 0;
        long b = fast(n);
        System.out.println("with a memo:     fib = " + b + ", calls = " + calls);
        // Time: about 1.6^n calls without the memo, O(n) with it. Space: O(n).
    }
}

