import java.util.*;

public class Main {
    static int[] coins = {5, 10, 25};
    static int[] memo;
    static int solved = 0;
    static final int INF = 1000000;

    // Top-down: recursion + cache. It only visits amounts it can actually reach.
    static int best(int a) {
        if (a == 0) return 0;
        if (a < 0) return INF;
        if (memo[a] != -1) return memo[a];
        solved++;
        int res = INF;
        for (int c : coins) res = Math.min(res, 1 + best(a - c));
        memo[a] = res;
        return res;
    }

    public static void main(String[] args) {
        int amount = 100;
        System.out.println("coins = [5, 10, 25], amount = " + amount);
        memo = new int[amount + 1];
        Arrays.fill(memo, -1);
        int top = best(amount);
        System.out.println("top-down  (memoization): fewest coins = " + top + ", states solved = " + solved);

        // Bottom-up: a loop fills every amount from 1 to 100 in order.
        int[] dp = new int[amount + 1];
        int filled = 0;
        for (int a = 1; a <= amount; a++) {
            dp[a] = INF;
            for (int c : coins) if (a >= c) dp[a] = Math.min(dp[a], 1 + dp[a - c]);
            filled++;
        }
        System.out.println("bottom-up (tabulation):  fewest coins = " + dp[amount] + ", states solved = " + filled);
        // Both: O(amount * coins) time worst case, O(amount) space.
        // Top-down also uses the call stack; bottom-up uses no recursion.
    }
}

