public class Main {
    static int endWith1 = 0, endWith2 = 0;

    // Brute force: build every sequence of 1-steps and 2-steps that sums to n.
    static void walk(int remaining, int lastStep) {
        if (remaining == 0) {
            if (lastStep == 1) endWith1++; else endWith2++;   // group by last move
            return;
        }
        if (remaining >= 1) walk(remaining - 1, 1);
        if (remaining >= 2) walk(remaining - 2, 2);
    }

    public static void main(String[] args) {
        int n = 5;
        // DP: ways[i] = ways[i-1] + ways[i-2]
        int[] ways = new int[n + 1];
        ways[0] = 1;
        ways[1] = 1;
        for (int i = 2; i <= n; i++) ways[i] = ways[i - 1] + ways[i - 2];

        walk(n, 0);
        System.out.println("n = " + n);
        System.out.println("sequences whose last move is 1 step:  " + endWith1 + "  (ways(" + (n - 1) + ") = " + ways[n - 1] + ")");
        System.out.println("sequences whose last move is 2 steps: " + endWith2 + "  (ways(" + (n - 2) + ") = " + ways[n - 2] + ")");
        // The two groups share nothing and cover everything, so we just add.
        System.out.println("total by listing = " + (endWith1 + endWith2) + ", ways(" + n + ") by DP = " + ways[n]);
        // DP: O(n) time, O(n) space. Listing: about 1.6^n time.
    }
}

