public class Main {
    // Greedy: always take the biggest coin that still fits (coins sorted ascending).
    static int greedy(int[] coins, int amount) {
        int used = 0;
        for (int i = coins.length - 1; i >= 0; i--) {
            used += amount / coins[i];
            amount %= coins[i];
        }
        return used;
    }

    // DP: dp[a] = fewest coins for amount a = 1 + min over every possible last coin.
    static int dp(int[] coins, int amount) {
        int INF = 1000000;
        int[] dp = new int[amount + 1];
        for (int a = 1; a <= amount; a++) {
            dp[a] = INF;
            for (int c : coins) if (a >= c) dp[a] = Math.min(dp[a], 1 + dp[a - c]);
        }
        return dp[amount];
    }

    public static void main(String[] args) {
        int[] odd = {1, 3, 4};
        System.out.println("coins = [1, 3, 4], amount = 6");
        System.out.println("  greedy = " + greedy(odd, 6) + " coins, DP = " + dp(odd, 6) + " coins");
        int[] us = {1, 5, 10, 25};
        System.out.println("coins = [1, 5, 10, 25], amount = 63");
        System.out.println("  greedy = " + greedy(us, 63) + " coins, DP = " + dp(us, 63) + " coins");
        // Greedy: O(coins) time. DP: O(amount * coins) time, O(amount) space.
    }
}

