    static int Greedy(int[] coins, int amount) {
        int used = 0;
        for (int i = coins.Length - 1; i >= 0; i--) {
            used += amount / coins[i];
            amount %= coins[i];
        }
        return used;
    }

    // DP: dp[a] = fewest coins for amount a = 1 + min over every possible last coin.
    static int Dp(int[] coins, int amount) {
        int INF = 1000000;
        int[] dp = new int[amount + 1];
        for (int a = 1; a <= amount; a++) {
            dp[a] = INF;
            foreach (int c in coins) if (a >= c) dp[a] = Math.Min(dp[a], 1 + dp[a - c]);
        }
        return dp[amount];
    }

    static void Main() {
        int[] odd = {1, 3, 4};
        Console.WriteLine("coins = [1, 3, 4], amount = 6");
        Console.WriteLine("  greedy = " + Greedy(odd, 6) + " coins, DP = " + Dp(odd, 6) + " coins");
        int[] us = {1, 5, 10, 25};
        Console.WriteLine("coins = [1, 5, 10, 25], amount = 63");
        Console.WriteLine("  greedy = " + Greedy(us, 63) + " coins, DP = " + Dp(us, 63) + " coins");
        // Greedy: O(coins) time. DP: O(amount * coins) time, O(amount) space.
    }
}

