public class Main {
    public static void main(String[] args) {
        int[] w = {1, 3, 4, 5};
        int[] v = {1, 4, 5, 7};
        int n = w.length, W = 7;
        System.out.println("weights = [1, 3, 4, 5], values = [1, 4, 5, 7], capacity = 7");

        // 2D: dp[i][c] = best value using the first i items with capacity c.
        int[][] dp = new int[n + 1][W + 1];
        for (int i = 1; i <= n; i++)
            for (int c = 0; c <= W; c++) {
                dp[i][c] = dp[i - 1][c];                        // skip item i
                if (c >= w[i - 1])                              // or take it once
                    dp[i][c] = Math.max(dp[i][c], dp[i - 1][c - w[i - 1]] + v[i - 1]);
            }
        System.out.println("2D table answer = " + dp[n][W]);

        // 1D: go from W down, so one[c - w] is still the previous row.
        int[] one = new int[W + 1];
        for (int i = 0; i < n; i++)
            for (int c = W; c >= w[i]; c--)
                one[c] = Math.max(one[c], one[c - w[i]] + v[i]);
        System.out.println("1D array answer = " + one[W]);

        // Walk back through the 2D table: a change between rows means "taken".
        int c = W;
        for (int i = n; i >= 1; i--)
            if (dp[i][c] != dp[i - 1][c]) {
                System.out.println("took item " + (i - 1) + " (weight " + w[i - 1] + ", value " + v[i - 1] + ")");
                c -= w[i - 1];
            }
        // Time O(n * W). Space O(n * W) for 2D, O(W) for 1D.
    }
}

