code.java:
public class Main {
    public static void main(String[] args) {
        int[] w = {1, 3, 4};
        int[] v = {15, 50, 60};
        int W = 8;
        System.out.println("weights = [1, 3, 4], values = [15, 50, 60], capacity = 8");

        // 0/1: capacity goes DOWN, so dp[c - w] has not used this item yet.
        int[] once = new int[W + 1];
        for (int i = 0; i < w.length; i++)
            for (int c = W; c >= w[i]; c--)
                once[c] = Math.max(once[c], once[c - w[i]] + v[i]);

        // Unbounded: capacity goes UP, so dp[c - w] may already include this item.
        int[] many = new int[W + 1];
        for (int i = 0; i < w.length; i++)
            for (int c = w[i]; c <= W; c++)
                many[c] = Math.max(many[c], many[c - w[i]] + v[i]);

        System.out.println("0/1 knapsack (each item once)  = " + once[W]);
        System.out.println("unbounded (items can repeat)   = " + many[W]);
        // The only change is the direction of the inner loop.
        // Both: O(n * W) time, O(W) space.
    }
}

