public class Main {
    public static void main(String[] args) {
        String a = "ABCBDAB", b = "BDCABA";
        int n = a.length(), m = b.length();
        System.out.println("a = " + a + ", b = " + b);

        // dp[i][j] = LCS length of the first i chars of a and first j chars of b.
        int[][] dp = new int[n + 1][m + 1];
        for (int i = 1; i <= n; i++)
            for (int j = 1; j <= m; j++)
                if (a.charAt(i - 1) == b.charAt(j - 1)) dp[i][j] = dp[i - 1][j - 1] + 1;
                else dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);

        // Walk back from the bottom-right corner to collect the characters.
        StringBuilder sb = new StringBuilder();
        int i = n, j = m;
        while (i > 0 && j > 0) {
            if (a.charAt(i - 1) == b.charAt(j - 1)) {       // match: keep it, go diagonal
                sb.append(a.charAt(i - 1));
                i--;
                j--;
            } else if (dp[i - 1][j] >= dp[i][j - 1]) i--;   // otherwise follow the larger side
            else j--;
        }
        sb.reverse();                                        // collected back to front
        System.out.println("LCS length = " + dp[n][m]);
        System.out.println("one LCS    = " + sb);
        System.out.println("table cells kept = " + ((n + 1) * (m + 1)));
        // Time O(n * m). Space O(n * m): the walk back needs the whole table.
    }
}

