code.java:
public class Main {
    // Full table: dp[i][j] = edits to turn the first i chars of a into the first j of b.
    static int full(String a, String b) {
        int n = a.length(), m = b.length();
        int[][] dp = new int[n + 1][m + 1];
        for (int i = 0; i <= n; i++) dp[i][0] = i;           // delete everything
        for (int j = 0; j <= m; j++) dp[0][j] = j;           // insert everything
        for (int i = 1; i <= n; i++)
            for (int j = 1; j <= m; j++) {
                int same = a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1;
                dp[i][j] = Math.min(dp[i - 1][j - 1] + same,           // keep or replace
                           Math.min(dp[i - 1][j] + 1, dp[i][j - 1] + 1)); // delete, insert
            }
        return dp[n][m];
    }

    // One row: 'diag' saves the old dp[i-1][j-1] before it is overwritten.
    static int oneRow(String a, String b) {
        int n = a.length(), m = b.length();
        int[] row = new int[m + 1];
        for (int j = 0; j <= m; j++) row[j] = j;
        for (int i = 1; i <= n; i++) {
            int diag = row[0];
            row[0] = i;
            for (int j = 1; j <= m; j++) {
                int up = row[j];
                int same = a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1;
                row[j] = Math.min(diag + same, Math.min(up + 1, row[j - 1] + 1));
                diag = up;
            }
        }
        return row[m];
    }

