public class Main {
    static String yesNo(boolean x) { return x ? "yes" : "no"; }

    public static void main(String[] args) {
        int[] nums = {3, 4, 12, 5, 2, 20};
        int limit = 63;                                   // sums 0..63 fit in one 64-bit word
        System.out.println("nums = [3, 4, 12, 5, 2, 20]");

        // Classic boolean table: one array cell per sum.
        boolean[] can = new boolean[limit + 1];
        can[0] = true;
        for (int x : nums)
            for (int s = limit; s >= x; s--)
                if (can[s - x]) can[s] = true;

        // Bitset: bit s of 'bits' is 1 when sum s is reachable.
        // Shifting left by x adds x to every reachable sum at once.
        long bits = 1L;
        for (int x : nums) bits |= bits << x;

        int[] targets = {9, 30, 45, 47};
        for (int t : targets)
            System.out.println("sum " + t + ": table says " + yesNo(can[t])
                    + ", bitset says " + yesNo(((bits >>> t) & 1L) == 1L));
        System.out.println("memory: table = " + (limit + 1) + " cells, bitset = 1 word of 64 bits");
        // Table: O(n * S) time, O(S) cells. Bitset: O(n * S / 64) time, S / 64 words.
    }
}

