public class Main {
    public static void main(String[] args) {
        // Unique Paths II: 1 = obstacle. Fill FORWARD: ways depend on cells above/left.
        int[][] grid = {{0, 0, 0}, {0, 1, 0}, {0, 0, 0}};
        int R = 3, C = 3;
        int[][] ways = new int[R][C];
        for (int r = 0; r < R; r++)
            for (int c = 0; c < C; c++) {
                if (grid[r][c] == 1) { ways[r][c] = 0; continue; }
                if (r == 0 && c == 0) { ways[r][c] = 1; continue; }
                int up = r > 0 ? ways[r - 1][c] : 0;
                int left = c > 0 ? ways[r][c - 1] : 0;
                ways[r][c] = up + left;
            }
        System.out.println("obstacle grid = [[0,0,0],[0,1,0],[0,0,0]]");
        System.out.println("unique paths (filled forward) = " + ways[R - 1][C - 1]);

        // Dungeon Game: fill BACKWARD: need[r][c] = least health when entering the cell.
        int[][] d = {{-2, -3, 3}, {-5, -10, 1}, {10, 30, -5}};
        int BIG = 1000000000;
        int[][] need = new int[R + 1][C + 1];
        for (int r = 0; r <= R; r++)
            for (int c = 0; c <= C; c++) need[r][c] = BIG;
        need[R][C - 1] = 1;                      // border next to the goal: leave with 1 health
        need[R - 1][C] = 1;
        for (int r = R - 1; r >= 0; r--)
            for (int c = C - 1; c >= 0; c--) {
                int next = Math.min(need[r + 1][c], need[r][c + 1]);   // cheaper way onward
                need[r][c] = Math.max(1, next - d[r][c]);              // never below 1
            }
        System.out.println("dungeon = [[-2,-3,3],[-5,-10,1],[10,30,-5]]");
        System.out.println("minimum starting health (filled backward) = " + need[0][0]);
        // Both: O(R * C) time and space.
    }
}

