code.java:
public class Main {
    public static void main(String[] args) {
        long[] w = {400000000L, 300000000L, 500000000L, 600000000L};
        int[] v = {4, 5, 7, 8};
        long W = 1000000000L;
        System.out.println("weights = [400000000, 300000000, 500000000, 600000000]");
        System.out.println("values  = [4, 5, 7, 8], capacity = 1000000000");

        // A table indexed by capacity would need 10^9 cells. Index by VALUE instead:
        // minW[x] = smallest total weight that reaches value exactly x.
        int total = 0;
        for (int x : v) total += x;
        long INF = Long.MAX_VALUE;
        long[] minW = new long[total + 1];
        for (int x = 1; x <= total; x++) minW[x] = INF;
        for (int i = 0; i < w.length; i++)
            for (int x = total; x >= v[i]; x--)             // downward: each item once
                if (minW[x - v[i]] != INF)
                    minW[x] = Math.min(minW[x], minW[x - v[i]] + w[i]);

        // Answer: the largest value whose lightest weight still fits.
        int best = 0;
        for (int x = 0; x <= total; x++) if (minW[x] <= W) best = x;
        System.out.println("best value = " + best + " (weight used = " + minW[best] + ")");
        System.out.println("table size = " + (total + 1) + " cells instead of 1000000001");
        // Time O(n * sum of values), space O(sum of values).
    }
}

